*** Begin Patch
*** Update File: /home/mi/vela_competition/contest/contest2026_264_VelaSightsuixingAIzhinengyanjing/board/beken/boards/bk7258/bk7258-ap/Kconfig
@@
 config BK7258_BT_GATT_TEST
 	bool "BK7258 Bluetooth GATT acceptance fixture"
@@
 		Register a test-only GATT service with read/write and notification
 		characteristics. Keep this disabled in production images.
+
+config BK7258_SDIO_AUTOINIT_DELAY_MS
+	int "SD-NAND asynchronous initialization delay (ms)"
+	default 15000
+	range 0 60000
+	depends on BK7258_SDIO && SCHED_LPWORK
+	help
+		Schedule fixed SD-NAND initialization on LPWORK after this delay.
+		Board bring-up continues immediately. The default reflects the measured
+		physical-reset test where initialization succeeded after startup settled.

 endif
*** Update File: /home/mi/vela_competition/contest/contest2026_264_VelaSightsuixingAIzhinengyanjing/board/beken/boards/bk7258/bk7258-ap/configs/nsh/defconfig
@@
 CONFIG_MMCSD_READONLY=y
+CONFIG_BK7258_SDIO_AUTOINIT_DELAY_MS=15000
 CONFIG_SDIO_BLOCKSETUP=y
*** Update File: /home/mi/vela_competition/contest/contest2026_264_VelaSightsuixingAIzhinengyanjing/board/beken/boards/bk7258/bk7258-ap/src/bk7258_bringup.c
@@
 #ifdef CONFIG_BK7258_SDIO
 int bk7258_mmcsd_initialize(void);
+int bk7258_mmcsd_schedule(unsigned int delay_ms);
 #endif
@@
 #ifdef CONFIG_BK7258_SDIO
-  /* SD-NAND initialization is temporarily deferred to the sdnand_init NSH
-   * command while physical-RST timing is characterized. */
+  ret = bk7258_mmcsd_schedule(CONFIG_BK7258_SDIO_AUTOINIT_DELAY_MS);
+  if (ret < 0)
+    {
+      printf("SD-NAND delayed initialization schedule failed, error=%d\n",
+             ret);
+    }
 #endif
*** Update File: /home/mi/vela_competition/contest/contest2026_264_VelaSightsuixingAIzhinengyanjing/board/beken/boards/bk7258/bk7258-ap/src/bk7258_mmcsd.c
@@
 #include <nuttx/fs/partition.h>
 #include <nuttx/fs/fs.h>
 #include <nuttx/mmcsd.h>
+#include <nuttx/mutex.h>
 #include <nuttx/sdio.h>
 #include <nuttx/signal.h>
+#include <nuttx/wqueue.h>
@@
 #define BK7258_MMCSD_PROBE_WAIT_MS 7000
 #define BK7258_MMCSD_PROBE_POLL_US 250000
+
+enum bk7258_mmcsd_state_e
+{
+  BK7258_MMCSD_NOT_STARTED = 0,
+  BK7258_MMCSD_RUNNING,
+  BK7258_MMCSD_COMPLETE
+};
+
+static mutex_t g_mmcsd_lock = NXMUTEX_INITIALIZER;
+static struct work_s g_mmcsd_work;
+static enum bk7258_mmcsd_state_e g_mmcsd_state;
+static int g_mmcsd_result = -EAGAIN;
@@
-int bk7258_mmcsd_initialize(void)
+static int bk7258_mmcsd_probe(void)
 {
@@
   return OK;
 }
+
+int bk7258_mmcsd_initialize(void)
+{
+  FAR struct inode *inode;
+  int ret;
+
+  ret = nxmutex_lock(&g_mmcsd_lock);
+  if (ret < 0)
+    {
+      return ret;
+    }
+
+  if (g_mmcsd_state == BK7258_MMCSD_COMPLETE)
+    {
+      ret = open_blockdriver("/dev/mmcsd0", MS_RDONLY, &inode);
+      if (ret == OK)
+        {
+          close_blockdriver(inode);
+        }
+      else
+        {
+          ret = g_mmcsd_result;
+        }
+
+      nxmutex_unlock(&g_mmcsd_lock);
+      return ret;
+    }
+
+  g_mmcsd_state = BK7258_MMCSD_RUNNING;
+  ret = bk7258_mmcsd_probe();
+  g_mmcsd_result = ret;
+  g_mmcsd_state = BK7258_MMCSD_COMPLETE;
+  nxmutex_unlock(&g_mmcsd_lock);
+  return ret;
+}
+
+static void bk7258_mmcsd_worker(FAR void *arg)
+{
+  int ret;
+
+  (void)arg;
+  printf("SD-NAND delayed initialization begin\n");
+  ret = bk7258_mmcsd_initialize();
+  if (ret < 0)
+    {
+      printf("SD-NAND delayed initialization failed, error=%d\n", ret);
+    }
+  else
+    {
+      printf("SD-NAND delayed initialization complete\n");
+    }
+}
+
+int bk7258_mmcsd_schedule(unsigned int delay_ms)
+{
+  int ret;
+
+  ret = nxmutex_lock(&g_mmcsd_lock);
+  if (ret < 0)
+    {
+      return ret;
+    }
+
+  if (g_mmcsd_state != BK7258_MMCSD_NOT_STARTED ||
+      !work_available(&g_mmcsd_work))
+    {
+      nxmutex_unlock(&g_mmcsd_lock);
+      return OK;
+    }
+
+  ret = work_queue(LPWORK, &g_mmcsd_work, bk7258_mmcsd_worker, NULL,
+                   MSEC2TICK(delay_ms));
+  nxmutex_unlock(&g_mmcsd_lock);
+
+  if (ret == OK)
+    {
+      printf("SD-NAND initialization scheduled in %u ms\n", delay_ms);
+    }
+
+  return ret;
+}
*** End Patch

