+int bk7258_sdio_clock_request(bool enable)
+{
+  int ret;
+
+  if (!enable)
+    {
+      ret = pwc_send_wait(0x2u, PM_CLOCK_SDIO, 0u, 0u);
+      if (ret < 0)
