 #include <nuttx/fs/fs.h>
 #include <nuttx/fs/ioctl.h>
+#include <nuttx/drivers/drivers.h>
@@
 #define SDNAND_SECTOR_SIZE 512
+#define SDNAND_FORMAT_DEV  "/dev/sdnandfmt"
 #define SDNAND_MARKER      CONFIG_BK7258_SDNAND_MOUNTPOINT \
                            "/.vela-persistence-test"
@@
 static int sdnand_provision(void)
 {
 #ifdef CONFIG_FSUTILS_MKFATFS
   struct fat_format_s fmt = FAT_FORMAT_INITIALIZER;
+  bool format_registered = false;
   int ret;
@@
   fmt.ff_fattype = 32;
   memcpy(fmt.ff_volumelabel, "VELASIGHT  ", 11);
   printf("SD-NAND formatting /dev/mmcsd0 as FAT32\n");
-  if (mkfatfs("/dev/mmcsd0", &fmt) < 0)
+  ret = bchdev_register("/dev/mmcsd0", SDNAND_FORMAT_DEV, O_RDWR);
+  if (ret < 0)
+    {
+      printf("SD-NAND format device registration failed: %d\n", ret);
+      return ret;
+    }
+
+  format_registered = true;
+  if (mkfatfs(SDNAND_FORMAT_DEV, &fmt) < 0)
     {
       ret = -errno;
       printf("SD-NAND FAT32 format failed: %d\n", ret);
-      return ret;
+      goto out_unregister;
     }

+  ret = OK;
+
+out_unregister:
+  if (format_registered)
+    {
+      int unregister_ret = bchdev_unregister(SDNAND_FORMAT_DEV);
+
+      if (unregister_ret < 0 && ret == OK)
+        {
+          ret = unregister_ret;
+        }
+    }
+
+  if (ret < 0)
+    {
+      return ret;
+    }
+
   ret = bk7258_mmcsd_mount("/dev/mmcsd0");
