+  else if (strcmp(command, "provision") == 0 && confirmed)
+    {
+      ret = sdnand_provision();
+    }
+  else
+    {
+      sdnand_usage();
+      return EXIT_FAILURE;
+    }
+
+  if (ret < 0)
+    {
+      printf("SD-NAND %s failed: %d\n", command, ret);
