+
+  if (!bk7258_block_exists(mount_source))
+    {
+      return -ENOENT;
+    }
+
+  if (mkdir("/mnt", 0777) < 0 && errno != EEXIST)
+    {
+      return -errno;
+    }
+
+  if (mkdir(CONFIG_BK7258_SDNAND_MOUNTPOINT, 0777) < 0 && errno != EEXIST)
