+int bk7258_mmcsd_maintenance_begin(void)
+{
+  char path[sizeof("/dev/mmcsd0p0")];
+  unsigned int index;
+  int ret;
+
+  ret = nxmutex_lock(&g_mmcsd_lock);
+  if (ret < 0)
+    {
+      return ret;
+    }
+
+  if (g_mmcsd_state != BK7258_MMCSD_COMPLETE ||
+      !bk7258_block_exists("/dev/mmcsd0"))
+    {
+      ret = -ENODEV;
+      goto out_unlock;
+    }
+
+  if (g_mmcsd_maintenance)
+    {
+      ret = -EBUSY;
+      goto out_unlock;
+    }
